'use client';

import { useState } from 'react';

import { useAutoplay } from '@/registry/ndeko/hooks/use-autoplay';
import { PRESS_LEAD_MS, usePress } from '@/registry/ndeko/lib/demonstration';
import { TrendingUpIcon } from '@/registry/ndeko/lib/icons';
import { Badge } from '@/registry/ndeko/ui/badge';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';

import { CUSTOMERS, SECTION } from './data';
import { FeaturedResult } from './featured-result';
import { WallCard } from './wall-card';

/** Long enough to read a featured quote once it has written itself in. */
const FEATURE_MS = 6200;

function indexAfter(index: number) {
  const next = index + 1;
  return next % CUSTOMERS.length;
}

/** The next customer after each one, so a round ends on the first customer and the loop shows no seam. */
const ROTATION = CUSTOMERS.map((_, index) => indexAfter(index));

function spokenFeatureOf(index: number) {
  const { company, result } = CUSTOMERS[index];
  return `Featured: ${company}, ${result.percent}% ${result.label}`;
}

export default function Testimonials05() {
  const [featuredIndex, setFeaturedIndex] = useState(0);
  const [hasChanged, setHasChanged] = useState(false);
  const [isReading, setIsReading] = useState(false);
  const [message, setMessage] = useState('');
  const { pressed, press } = usePress<string>();
  const featured = CUSTOMERS[featuredIndex];

  function feature(index: number) {
    setFeaturedIndex(index);
    setHasChanged(true);
  }

  const steps = ROTATION.flatMap((index) => [
    { after: FEATURE_MS, run: () => press(CUSTOMERS[index].id) },
    { after: PRESS_LEAD_MS, run: () => feature(index) },
  ]);
  const { ref } = useAutoplay<HTMLElement>(steps, {
    loopAfter: 0,
    isEnabled: !isReading,
  });

  function featureByPerson(customerId: string) {
    const index = CUSTOMERS.findIndex((customer) => customer.id === customerId);
    feature(index);
    setMessage(spokenFeatureOf(index));
  }

  /** The featured quote does not change under the pointer of someone reading it. */
  function holdWhileReading(event: React.PointerEvent<HTMLDivElement>) {
    if (event.pointerType === 'mouse') {
      setIsReading(true);
    }
  }

  function stopReading() {
    setIsReading(false);
  }

  return (
    <section ref={ref} className='@container'>
      <div className='mx-auto flex max-w-6xl flex-col gap-10 px-4 py-16 @2xl:px-6 @2xl:py-24 @5xl:px-8'>
        <header className='flex flex-wrap items-end justify-between gap-x-6 gap-y-4'>
          <div className='flex max-w-2xl flex-col gap-3'>
            <p className='text-primary-ink flex items-center gap-1.5 text-[13px] font-medium'>
              <TrendingUpIcon className='size-4' />
              {SECTION.label}
            </p>
            <h2 className='text-2xl font-semibold text-balance @2xl:text-3xl'>
              {SECTION.title}
            </h2>
            <p className='text-muted-foreground text-base text-pretty'>
              {SECTION.lead}
            </p>
          </div>
          <div className='flex flex-wrap items-center gap-2'>
            <Badge variant='secondary'>Sample quotes</Badge>
            <Badge variant='secondary'>Illustrative figures</Badge>
          </div>
        </header>
        <div className='flex flex-col gap-4'>
          <div onPointerEnter={holdWhileReading} onPointerLeave={stopReading}>
            <FeaturedResult
              customer={featured}
              position={featuredIndex}
              isStreamed={hasChanged}
            />
          </div>
          <ul className='grid gap-3 @xl:grid-cols-2 @4xl:grid-cols-3'>
            {CUSTOMERS.map((customer, index) => (
              <li key={customer.id}>
                <WallCard
                  customer={customer}
                  isFeatured={index === featuredIndex}
                  isPressed={pressed === customer.id}
                  onFeature={featureByPerson}
                />
              </li>
            ))}
          </ul>
        </div>
      </div>
      <LiveRegion message={message} />
    </section>
  );
}

'use client';

import { MotionNumber } from '@/components/core/motion-number';
import { WordRoll } from '@/components/core/word-roll';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { TrendingDownIcon, TrendingUpIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { Avatar } from '@/registry/ndeko/ui/avatar';
import { Swap } from '@/registry/ndeko/ui/chat-motion';
import { CompanyMark } from '@/registry/ndeko/ui/company-mark';
import { StreamedInk } from '@/registry/ndeko/ui/streamed-text';
import { Wash } from '@/registry/ndeko/ui/wash';

import { CUSTOMERS, type Customer } from './data';

const RESULT_LABELS = CUSTOMERS.map((customer) => customer.result.label);

const PERCENT_SUFFIX = '%';

const WORD_MS = 38;

const FADE_IN =
  'transition-opacity duration-300 ease-(--ease-out-strong) starting:opacity-0';

/** The quote a visitor reaches first is already written: only a quote that replaced another one arrives. */
function arrivalOf(isStreamed: boolean) {
  if (isStreamed) {
    return FADE_IN;
  }
  return undefined;
}

/** Under reduced motion a new quote fades in whole instead of word by word. */
function wholeQuoteFadeOf(isStreamed: boolean, shouldReduceMotion: boolean) {
  if (!shouldReduceMotion) {
    return undefined;
  }
  return arrivalOf(isStreamed);
}

type FeaturedResultProps = {
  customer: Customer;
  /** The place of the customer in the list, so the label rolls in the direction of the change. */
  position: number;
  isStreamed: boolean;
};

export function FeaturedResult({
  customer,
  position,
  isStreamed,
}: FeaturedResultProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const { person, result } = customer;
  const isUp = result.trend === 'up';
  const isWordByWord = isStreamed && !shouldReduceMotion;

  return (
    <div className='bg-card hairline-ring ring-border dark:bg-foreground/[0.04] relative isolate grid grid-cols-1 gap-8 rounded-2xl p-6 shadow-[0_1px_2px_rgb(0_0_0/0.04)] @2xl:p-8 @3xl:grid-cols-[minmax(0,1fr)_17rem] @3xl:gap-12'>
      <Wash />
      <figure className='flex flex-col justify-between gap-8'>
        <blockquote className='grid text-lg leading-8 font-medium text-pretty *:col-start-1 *:row-start-1 @3xl:text-xl @3xl:leading-8'>
          {CUSTOMERS.map((candidate) => (
            <p key={candidate.id} aria-hidden='true' className='invisible'>
              {candidate.long}
            </p>
          ))}
          <p
            key={customer.id}
            className={wholeQuoteFadeOf(isStreamed, shouldReduceMotion)}
          >
            <StreamedInk
              text={customer.long}
              isStreaming={isWordByWord}
              wordMs={WORD_MS}
            />
          </p>
        </blockquote>
        <figcaption
          key={customer.id}
          className={cn('flex items-center gap-3', arrivalOf(isStreamed))}
        >
          <Avatar seed={person.name} className='size-10' />
          <span className='flex min-w-0 flex-1 flex-col'>
            <span className='truncate text-sm font-medium'>{person.name}</span>
            <span className='text-muted-foreground truncate text-[13px]'>
              {person.role}, {customer.company}
            </span>
          </span>
          <CompanyMark seed={customer.company} size='lg' />
        </figcaption>
      </figure>
      <div className='bg-foreground/[0.04] flex flex-col justify-between gap-6 rounded-xl p-5'>
        <span className='text-muted-foreground text-xs'>
          The number that moved
        </span>
        <div className='flex flex-col gap-2'>
          <MotionNumber
            value={result.percent}
            suffix={PERCENT_SUFFIX}
            className='text-5xl font-semibold'
          />
          <span className='text-muted-foreground flex items-center gap-1.5 text-sm'>
            <Swap swapKey={result.trend} className='text-success-foreground'>
              {isUp && <TrendingUpIcon className='size-4' />}
              {!isUp && <TrendingDownIcon className='size-4' />}
            </Swap>
            <WordRoll
              text={result.label}
              labels={RESULT_LABELS}
              value={position}
            />
          </span>
        </div>
      </div>
    </div>
  );
}

import { pressedQuietOf } from '@/registry/ndeko/lib/demonstration';
import { TrendingDownIcon, TrendingUpIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { Avatar } from '@/registry/ndeko/ui/avatar';
import { Badge } from '@/registry/ndeko/ui/badge';

import type { Customer, Result } from './data';

function chipTextOf(result: Result) {
  return `${result.percent}% ${result.label}`;
}

function featuredToneOf(isFeatured: boolean) {
  if (isFeatured) {
    return 'ring-primary/50 bg-primary/[0.04] dark:bg-primary/[0.08]';
  }
  return 'ring-border bg-card hover:bg-foreground/[0.02] dark:bg-foreground/[0.04] dark:hover:bg-foreground/[0.06]';
}

type WallCardProps = {
  customer: Customer;
  isFeatured: boolean;
  isPressed: boolean;
  onFeature: (customerId: string) => void;
};

export function WallCard({
  customer,
  isFeatured,
  isPressed,
  onFeature,
}: WallCardProps) {
  const { person, result } = customer;
  const isUp = result.trend === 'up';

  return (
    <button
      type='button'
      aria-pressed={isFeatured}
      onClick={() => onFeature(customer.id)}
      className={cn(
        'hairline-ring focus-visible:ring-ring focus-visible:ring-offset-background flex h-full w-full cursor-pointer flex-col items-start gap-4 rounded-xl p-4 text-start shadow-[0_1px_2px_rgb(0_0_0/0.04)] transition-[background-color,box-shadow,scale] duration-150 ease-(--ease-out-strong) outline-none focus-visible:ring-2 focus-visible:ring-offset-2 active:scale-[0.97]',
        featuredToneOf(isFeatured),
        pressedQuietOf(isPressed)
      )}
    >
      <span className='text-[13px] leading-5 text-pretty'>
        {customer.short}
      </span>
      <span className='flex w-full min-w-0 items-center gap-2'>
        <Avatar seed={person.name} className='size-6' />
        <span className='min-w-0 flex-1 truncate text-xs'>
          <span className='font-medium'>{person.name}</span>
          <span className='text-muted-foreground'>, {customer.company}</span>
        </span>
      </span>
      <Badge variant='success'>
        {isUp && <TrendingUpIcon />}
        {!isUp && <TrendingDownIcon />}
        <span className='tabular-nums'>{chipTextOf(result)}</span>
      </Badge>
    </button>
  );
}

export type Trend = 'down' | 'up';

/** A change measured in percent: the label carries its direction, "fewer late deliveries". */
export type Result = {
  percent: number;
  trend: Trend;
  label: string;
};

export type Customer = {
  id: string;
  person: {
    name: string;
    role: string;
  };
  company: string;
  short: string;
  long: string;
  result: Result;
};

